window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d7f44c7a24fcaf44"]={"versions": [{"id": "FIG-d7f44c7a24fcaf44", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Architektur- und Methodik-Transformationsdiagramm (Übergang vom plattformunabhängigen Metamodell zur ECU-spezifischen Deployment- und Laufzeitarchitektur).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des AUTOSAR-Grundprinzips: Vollständige funktionale Entkopplung der Anwendungslogik von der Ausführungs-Hardware über den <em>Virtual Functional Bus (VFB)</em> und dessen deterministische Transformation in die <em>Runtime Environment (RTE)</em> sowie den <em>Basic Software (BSW)</em>-Stack auf vernetzten Steuergeräten.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>VFB-Ebene (Logische Schicht):</strong>\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponentType</code> (<code>AUTOSAR SW-C 1..n</code>): Kapselung von Applikationscode und internem Verhalten (<em>Internal Behavior</em> mit <code>RunnableEntity</code>).\n</li><li><code>PortPrototype</code>: Typisiert über Port-Interfaces:\n<ul class=\"fig-list\"><li><em>Sender-Receiver (S/R):</em> Datenorientierter Informationsaustausch (gekennzeichnet durch Pfeil-/Trapez-Symbole).\n</li><li><em>Client-Server (C/S):</em> Funktionsorientierte Interaktion mit Request/Response-Charakter (Lollipop- [Provide] und Cup/Socket-Symbole [Require]).\n</li></ul>\n</li><li><code>AssemblySwConnector</code>: Virtuelle Punkt-zu-Punkt-Verbindungen zwischen kompatiblen Ports auf VFB-Ebene.\n</li></ul>\n</li><li><strong>Transformations- und Methodik-Artefakte:</strong>\n<ul class=\"fig-list\"><li><code>ECU Descriptions</code> (<code>EcuResourceDescription</code>): Hardware-Eigenschaften (CPU, RAM/ROM, Controller, Peripherie).\n</li><li><code>System Constraint Description</code>: Netzwerktopologie, Bus-Baudraten, Latenzanforderungen, Sicherheitsanforderungen.\n</li><li><code>Tool supporting deployment of SW components</code>: System-Authoring- und Deployment-Tool zur Allokation von SW-Cs auf ECUs (<code>SwcToEcuMapping</code>) und Generierung des System-/ECU-Extracts.\n</li></ul>\n</li><li><strong>Deployment-Ebene (Physische Schicht):</strong>\n<ul class=\"fig-list\"><li><code>ECU I .. ECU m</code>: Physische Steuergeräte-Instanzen.\n</li><li><code>AUTOSAR Runtime Environment (RTE)</code>: Steuergerätespezifisch generierte Middleware; bindet SW-C-Ports an lokale OS-Tasks oder an den BSW-Kommunikationsstack an.\n</li><li><code>Basic Software (BSW)</code>: Schichtenarchitektur bestehend aus Services Layer (OS, Com, Dem/Det), ECU Abstraction Layer, Microcontroller Abstraction Layer (MCAL) und Complex Device Drivers (CDD).\n</li><li><code>Kommunikationsbus &amp; Gateway</code>: Physisches Netzwerk (CAN, LIN, FlexRay) mit Gateway-Knoten zur PDU- bzw. Signalweiterleitung zwischen getrennten Netzwerkclustern.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Entwurfsphase (Plattformunabhängig):</strong>\n<ul class=\"fig-list\"><li>Modellierung der SW-C-Beschreibungen, Port-Interfaces und Runnables.\n</li><li>Verbindungsdefinition via VFB ohne Kenntnis von Ziel-ECU, Busprotokoll oder Speicheradressen.\n</li></ul>\n</li><li><strong>System-Synthese &amp; Mapping (Build-Time / Toolchain):</strong>\n<ul class=\"fig-list\"><li>SW-C-Allokation auf Ziel-ECUs (<code>ECU I</code>, <code>ECU II</code>, <code>ECU m</code>) unter Auswertung der Constraints.\n</li><li>Unterscheidung des Kommunikationspfades durch den RTE-Generator:\n<ul class=\"fig-list\"><li><em>Intra-ECU-Kommunikation:</em> RTE realisiert den Austausch direkt im Speicher (z. B. atomare Pufferkopie, Shared Variable unter Schutz von <code>ExclusiveArea</code> / OS-Interrupt-Sperre).\n</li><li><em>Inter-ECU-Kommunikation:</em> RTE transformiert Port-Aufrufe in Aufrufe der BSW-Kommunikationsschicht (<code>Rte</code> → <code>Com_SendSignal</code> / <code>Com_ReceiveSignal</code> → <code>PduR</code> → Bus Interface → Bus Driver).\n</li></ul>\n</li></ul>\n</li><li><strong>Laufzeitausführung (ECU Execution):</strong>\n<ul class=\"fig-list\"><li>Runnables werden durch <code>RTE-Events</code> getriggert (z. B. <code>TimingEvent</code> für periodische Ausführung, <code>DataReceivedEvent</code>, <code>OperationInvokedEvent</code>).\n</li><li>Die RTE bettet Runnables in den Kontext deterministischer Tasks des AUTOSAR OS ein.\n</li><li>Inter-ECU-Signale laufen über physische Controller, Transceiver und ggf. Gateways (<code>PduR</code>/<code>Com</code>-Gatewaying).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Applikations- &amp; Modellierungs-Entwickler (ASCET / Simulink / C):</strong>\n<ul class=\"fig-list\"><li>Absolutes Hardware- und Stack-Zugriffsverbot: Kein Aufruf von Treiber-APIs oder OS-Primitives (<code>WaitEvent</code>, <code>ActivateTask</code>) im Anwendungsquellcode.\n</li><li>Interaktion zwingend über standardisierte RTE-APIs (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Call_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Result_&lt;p&gt;_&lt;o&gt;</code>).\n</li><li>Runnables müssen reentrant sein, wenn sie in mehreren Instanzen oder Tasks laufen, und dürfen keine blockierenden Endlosschleifen enthalten.\n</li></ul>\n</li><li><strong>RTE- &amp; Integrations-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Zuordnung von Runnables zu OS-Tasks steuert Präemption und Latenz; Runnables gleicher Periodizität werden typischerweise sequenziell in einem gemeinsamen Basic- oder Extended-Task geclustert.\n</li><li>Datenkonsistenz: Konfiguration von <code>Implicit</code> (Copy-in/Copy-out bei Runnable-Start/Ende via Task-Buffer) vs. <code>Explicit</code> Read/Write (direkter Zugriff mit atomarem Puffer-/Interruptschutz).\n</li></ul>\n</li><li><strong>BSW- &amp; Netzwerk-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Signal-to-PDU-Mapping im <code>Com</code>-Modul bestimmt, ob Daten zyklisch, getriggert oder ereignisgesteuert übertragen werden.\n</li><li>Busüberlastung und Gateway-Latenzen wirken sich direkt auf VFB-Ende-zu-Ende-Laufzeiten aus und müssen im System-Timing-Modell abgesichert werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3cb35f41752e8338", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Konzeptionelles Architektur- und Methodik-Transformationsdiagramm (Übergang vom plattformunabhängigen Metamodell zur ECU-spezifischen Deployment- und Laufzeitarchitektur).\n</li><li><strong>Technischer Zweck:</strong> Visualisierung des AUTOSAR-Grundprinzips: Vollständige funktionale Entkopplung der Anwendungslogik von der Ausführungs-Hardware über den <em>Virtual Functional Bus (VFB)</em> und dessen deterministische Transformation in die <em>Runtime Environment (RTE)</em> sowie den <em>Basic Software (BSW)</em>-Stack auf vernetzten Steuergeräten.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>VFB-Ebene (Logische Schicht):</strong>\n<ul class=\"fig-list\"><li><code>AtomicSoftwareComponentType</code> (<code>AUTOSAR SW-C 1..n</code>): Kapselung von Applikationscode und internem Verhalten (<em>Internal Behavior</em> mit <code>RunnableEntity</code>).\n</li><li><code>PortPrototype</code>: Typisiert über Port-Interfaces:\n<ul class=\"fig-list\"><li><em>Sender-Receiver (S/R):</em> Datenorientierter Informationsaustausch (gekennzeichnet durch Pfeil-/Trapez-Symbole).\n</li><li><em>Client-Server (C/S):</em> Funktionsorientierte Interaktion mit Request/Response-Charakter (Lollipop- [Provide] und Cup/Socket-Symbole [Require]).\n</li></ul>\n</li><li><code>AssemblySwConnector</code>: Virtuelle Punkt-zu-Punkt-Verbindungen zwischen kompatiblen Ports auf VFB-Ebene.\n</li></ul>\n</li><li><strong>Transformations- und Methodik-Artefakte:</strong>\n<ul class=\"fig-list\"><li><code>ECU Descriptions</code> (<code>EcuResourceDescription</code>): Hardware-Eigenschaften (CPU, RAM/ROM, Controller, Peripherie).\n</li><li><code>System Constraint Description</code>: Netzwerktopologie, Bus-Baudraten, Latenzanforderungen, Sicherheitsanforderungen.\n</li><li><code>Tool supporting deployment of SW components</code>: System-Authoring- und Deployment-Tool zur Allokation von SW-Cs auf ECUs (<code>SwcToEcuMapping</code>) und Generierung des System-/ECU-Extracts.\n</li></ul>\n</li><li><strong>Deployment-Ebene (Physische Schicht):</strong>\n<ul class=\"fig-list\"><li><code>ECU I .. ECU m</code>: Physische Steuergeräte-Instanzen.\n</li><li><code>AUTOSAR Runtime Environment (RTE)</code>: Steuergerätespezifisch generierte Middleware; bindet SW-C-Ports an lokale OS-Tasks oder an den BSW-Kommunikationsstack an.\n</li><li><code>Basic Software (BSW)</code>: Schichtenarchitektur bestehend aus Services Layer (OS, Com, Dem/Det), ECU Abstraction Layer, Microcontroller Abstraction Layer (MCAL) und Complex Device Drivers (CDD).\n</li><li><code>Kommunikationsbus &amp; Gateway</code>: Physisches Netzwerk (CAN, LIN, FlexRay) mit Gateway-Knoten zur PDU- bzw. Signalweiterleitung zwischen getrennten Netzwerkclustern.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Entwurfsphase (Plattformunabhängig):</strong>\n<ul class=\"fig-list\"><li>Modellierung der SW-C-Beschreibungen, Port-Interfaces und Runnables.\n</li><li>Verbindungsdefinition via VFB ohne Kenntnis von Ziel-ECU, Busprotokoll oder Speicheradressen.\n</li></ul>\n</li><li><strong>System-Synthese &amp; Mapping (Build-Time / Toolchain):</strong>\n<ul class=\"fig-list\"><li>SW-C-Allokation auf Ziel-ECUs (<code>ECU I</code>, <code>ECU II</code>, <code>ECU m</code>) unter Auswertung der Constraints.\n</li><li>Unterscheidung des Kommunikationspfades durch den RTE-Generator:\n<ul class=\"fig-list\"><li><em>Intra-ECU-Kommunikation:</em> RTE realisiert den Austausch direkt im Speicher (z. B. atomare Pufferkopie, Shared Variable unter Schutz von <code>ExclusiveArea</code> / OS-Interrupt-Sperre).\n</li><li><em>Inter-ECU-Kommunikation:</em> RTE transformiert Port-Aufrufe in Aufrufe der BSW-Kommunikationsschicht (<code>Rte</code> → <code>Com_SendSignal</code> / <code>Com_ReceiveSignal</code> → <code>PduR</code> → Bus Interface → Bus Driver).\n</li></ul>\n</li></ul>\n</li><li><strong>Laufzeitausführung (ECU Execution):</strong>\n<ul class=\"fig-list\"><li>Runnables werden durch <code>RTE-Events</code> getriggert (z. B. <code>TimingEvent</code> für periodische Ausführung, <code>DataReceivedEvent</code>, <code>OperationInvokedEvent</code>).\n</li><li>Die RTE bettet Runnables in den Kontext deterministischer Tasks des AUTOSAR OS ein.\n</li><li>Inter-ECU-Signale laufen über physische Controller, Transceiver und ggf. Gateways (<code>PduR</code>/<code>Com</code>-Gatewaying).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Applikations- &amp; Modellierungs-Entwickler (ASCET / Simulink / C):</strong>\n<ul class=\"fig-list\"><li>Absolutes Hardware- und Stack-Zugriffsverbot: Kein Aufruf von Treiber-APIs oder OS-Primitives (<code>WaitEvent</code>, <code>ActivateTask</code>) im Anwendungsquellcode.\n</li><li>Interaktion zwingend über standardisierte RTE-APIs (<code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Write_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Call_&lt;p&gt;_&lt;o&gt;</code>, <code>Rte_Result_&lt;p&gt;_&lt;o&gt;</code>).\n</li><li>Runnables müssen reentrant sein, wenn sie in mehreren Instanzen oder Tasks laufen, und dürfen keine blockierenden Endlosschleifen enthalten.\n</li></ul>\n</li><li><strong>RTE- &amp; Integrations-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Zuordnung von Runnables zu OS-Tasks steuert Präemption und Latenz; Runnables gleicher Periodizität werden typischerweise sequenziell in einem gemeinsamen Basic- oder Extended-Task geclustert.\n</li><li>Datenkonsistenz: Konfiguration von <code>Implicit</code> (Copy-in/Copy-out bei Runnable-Start/Ende via Task-Buffer) vs. <code>Explicit</code> Read/Write (direkter Zugriff mit atomarem Puffer-/Interruptschutz).\n</li></ul>\n</li><li><strong>BSW- &amp; Netzwerk-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Signal-to-PDU-Mapping im <code>Com</code>-Modul bestimmt, ob Daten zyklisch, getriggert oder ereignisgesteuert übertragen werden.\n</li><li>Busüberlastung und Gateway-Latenzen wirken sich direkt auf VFB-Ende-zu-Ende-Laufzeiten aus und müssen im System-Timing-Modell abgesichert werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d7f44c7a24fcaf44", "to": "FIG-3cb35f41752e8338", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
